package com.truckload.controller;
import android.view.*;import android.widget.*;
/** Mode browsing is local; Apply is explicit and state comes from controller readback. */
final class LightingControls {
 private final MainActivity a;private final Telemetry m;final Spinner modeSelect;final TextView status;final Button apply;LinearLayout load,drive,work;private boolean dirty,syncing;private int requested=-1;private long sent;private boolean seenLights,seenDrive;
 private final String[] modes={"Load indication","Driving lights","Work lights","Automatic with GPS"};
 LightingControls(MainActivity activity,Telemetry model,LinearLayout parent){a=activity;m=model;LinearLayout c=a.card(parent,"Lighting mode",null);status=a.text("Connect to read active mode.",13,0xff54d6b4);c.addView(status);modeSelect=new Spinner(a);ArrayAdapter<String> items=new ArrayAdapter<>(a,android.R.layout.simple_spinner_item,modes);items.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);modeSelect.setAdapter(items);c.addView(modeSelect);modeSelect.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int i,long id){if(!syncing&&i!=actual())dirty=true;show(i);updateStatus();}});apply=a.button("Apply mode",this::apply,false);a.selected(apply,true);a.addButton(c,apply);}
 private int actual(){return m.lightMode.equals("WORK")?2:m.driveControl.equals("AUTO")?3:m.driveControl.equals("ON")?1:0;}
 void attach(LinearLayout loadPanel,LinearLayout drivePanel,LinearLayout workPanel){load=loadPanel;drive=drivePanel;work=workPanel;show(modeSelect.getSelectedItemPosition());}
 private void show(int mode){if(load==null)return;load.setVisibility(mode==0?View.VISIBLE:View.GONE);drive.setVisibility(mode==1||mode==3?View.VISIBLE:View.GONE);work.setVisibility(mode==2?View.VISIBLE:View.GONE);}
 private void apply(){if(!a.isConnected()||m.bench||requested>=0)return;int mode=modeSelect.getSelectedItemPosition();if((mode==1||mode==3)&&!m.extended){a.notice("This controller needs the driving firmware update.");return;}requested=mode;sent=android.os.SystemClock.elapsedRealtime();seenLights=seenDrive=false;if(mode==2){a.send("WORK_LIGHT|ON");}else{a.send("WORK_LIGHT|OFF");a.send("DRIVE_CONTROL|"+(mode==1?"ON":mode==3?"AUTO":"LOAD"));}update();}
 void record(String type,String line){if(type.equals("LIGHT_STATE"))seenLights=true;if(type.equals("DRIVE_CONFIG"))seenDrive=true;if(requested>=0&&seenLights&&(requested==2||seenDrive)&&actual()==requested){requested=-1;dirty=false;}if(type.equals("ERR")&&requested>=0){requested=-1;dirty=true;}update();}
 void disconnected(){requested=-1;seenLights=seenDrive=false;update();}
 void updateStatus(){if(status==null)return;String current=!a.isConnected()?"Connect to read active mode.":m.bench?"Bench test active · manage it in Testing & diagnostics":"Active: "+modes[actual()];status.setText(current+(requested>=0?"\nApplying… waiting for controller":dirty?"\nMode choice not applied":""));}
 void update(){if(requested>=0&&android.os.SystemClock.elapsedRealtime()-sent>6000){requested=-1;dirty=true;}if(!dirty&&requested<0){syncing=true;modeSelect.setSelection(actual());syncing=false;}modeSelect.setEnabled(requested<0);apply.setEnabled(a.isConnected()&&!m.bench&&requested<0);show(modeSelect.getSelectedItemPosition());updateStatus();}
}
